unsigned char  GetCfgMsg(unsigned char i)
{
	switch(i)
	{ 
		 case 0:  return TKChannelCfg[0][SET_TOUCH_FREQ];	  //0
		 case 1:  return TKChannelCfg[0][SET_RESOLUTION];	  //1
		 case 2:  return TKChannelCfg[0][SET_GAIN_CFG];		  //2		
		 case 3:  return GetBaseLineAdjustValue(0);//TKChannelCfg[0][SET_GAIN_CFG];
		 case 4:  return TKCFG[SET_ANTIJAM];			  //10 		0
		 default:return 0; 	 	
	}
}

